# Generated by Claude (Claude Code).
"""Charts of PeakCount training logs, on log scales.

plot_training_log: loss and error rate (1 - accuracy) per epoch of one run; used by
train.py after training. plot_comparison: error rates of several runs side by side.
plot_tuples: the functions of the adversarial tuples (adversary.py) with their samples.
plot_fixed_eval: loss and error rate per epoch on train.py's fixed evaluation set.
Not meant to be run on its own.
"""

import csv
import json
import math
from pathlib import Path

from matplotlib import rc_context
from matplotlib.figure import Figure
from matplotlib.ticker import FuncFormatter, LogLocator, MaxNLocator, NullFormatter

SURFACE = "#fcfcfb"
TEXT_PRIMARY = "#0b0b0b"
TEXT_SECONDARY = "#52514e"
TEXT_MUTED = "#898781"
GRIDLINE = "#e1e0d9"
AXIS = "#c3c2b7"
LOSS_COLOR = "#2a78d6"   # categorical slot 1 (blue)
ERROR_COLOR = "#eb6834"  # categorical slot 2 (orange)
# Categorical slots 1-6 (blue, orange, aqua, yellow, magenta, green), in fixed order, for
# comparing runs. Several of them are light on the surface, so lines also get direct labels.
RUN_COLORS = ["#2a78d6", "#eb6834", "#1baf7a", "#eda100", "#e87ba4", "#008300"]
LABEL_MIN_GAP = 0.05  # minimum vertical distance of end labels, as a fraction of the axes height

RC = {
    "font.family": ["Segoe UI", "DejaVu Sans"],
    "font.size": 10,
}


def decade_range(values: list[float]) -> tuple[int, int]:
    """Exponents (lo, hi) of the powers of 10 enclosing all values, at least one decade apart."""
    lo = math.floor(math.log10(min(values)))
    hi = math.ceil(math.log10(max(values)))
    return lo, max(hi, lo + 1)


def plain_decimal(value: float, _pos=None) -> str:
    """Format a power of ten without exponent notation: 1, 0.1, 0.00001."""
    decimals = max(0, -math.floor(math.log10(value) + 1e-9))
    return f"{value:.{decimals}f}"


def plain_percent(value: float, _pos=None) -> str:
    """Format a fraction that is a power of ten as a percentage: 100%, 1%, 0.001%."""
    return plain_decimal(100 * value) + "%"


def plot_training_log(csv_path: Path, png_path: Path) -> None:
    """Draw the training log at csv_path and save it as a PNG at png_path.

    The subtitle names the run by the folder that holds the CSV (runs/<date>_<time>/).

    Both y-axes are logarithmic and show the original values. An epoch with 100%
    accuracy would have error rate 0 (ln 0 = -inf); its error rate is clamped to
    1/n, the rate of a single mistake among that epoch's n functions.
    """
    csv_path = Path(csv_path)
    with open(csv_path, newline="") as f:
        rows = list(csv.DictReader(f))
    if not rows:
        raise ValueError(f"{csv_path} contains no epochs")

    epochs = [int(r["epoch"]) for r in rows]
    loss = [float(r["loss"]) for r in rows]
    seen = [int(r["functions_seen"]) for r in rows]
    per_epoch = [s - prev for s, prev in zip(seen, [0] + seen[:-1])]
    raw_error = [1.0 - float(r["accuracy"]) for r in rows]
    error = [max(e, 1.0 / n) for e, n in zip(raw_error, per_epoch)]
    clamped = sum(e < 1.0 / n for e, n in zip(raw_error, per_epoch))
    marker = "o" if len(rows) == 1 else None

    # Give both axes the same number of decades, so their decade ticks share gridlines.
    loss_lo, loss_hi = decade_range(loss)
    err_lo, err_hi = decade_range(error)
    decades = max(loss_hi - loss_lo, err_hi - err_lo)
    loss_lo, err_lo = loss_hi - decades, err_hi - decades

    with rc_context(RC):
        fig = Figure(figsize=(8, 4.8), dpi=150, facecolor=SURFACE)
        ax_loss = fig.add_subplot()
        ax_err = ax_loss.twinx()
        ax_loss.set_facecolor(SURFACE)

        # clip_on=False: values exactly on a power of ten at the axis edge stay fully visible.
        line_style = dict(linewidth=2, solid_capstyle="round", solid_joinstyle="round",
                          marker=marker, clip_on=False)
        (loss_line,) = ax_loss.plot(epochs, loss, color=LOSS_COLOR,
                                    label="Loss (left axis)", **line_style)
        (err_line,) = ax_err.plot(epochs, error, color=ERROR_COLOR,
                                  label="Error rate 1 − accuracy (right axis)", **line_style)

        if len(epochs) == 1:
            ax_loss.set_xlim(epochs[0] - 0.5, epochs[0] + 0.5)
            ax_loss.set_xticks(epochs)
        else:
            ax_loss.set_xlim(epochs[0], epochs[-1])
            ax_loss.xaxis.set_major_locator(MaxNLocator(integer=True))

        for ax, lo, hi, fmt in (
            (ax_loss, loss_lo, loss_hi, plain_decimal),
            (ax_err, err_lo, err_hi, plain_percent),
        ):
            ax.set_yscale("log")
            ax.set_ylim(10.0**lo, 10.0**hi)
            ax.yaxis.set_major_locator(LogLocator(base=10, numticks=decades + 2))
            ax.yaxis.set_major_formatter(FuncFormatter(fmt))
            ax.yaxis.set_minor_formatter(NullFormatter())

        ax_loss.set_xlabel("Epoch", color=TEXT_SECONDARY)
        ax_loss.set_ylabel("Loss (cross-entropy, log scale)", color=TEXT_SECONDARY)
        ax_err.set_ylabel("Error rate (log scale)", color=TEXT_SECONDARY)

        # Gridlines from the loss axis only, so the two scales don't draw two grids.
        ax_loss.grid(axis="y", which="major", color=GRIDLINE, linewidth=1)
        ax_loss.set_axisbelow(True)

        for ax in (ax_loss, ax_err):
            ax.spines["top"].set_visible(False)
            for side in ("left", "right", "bottom"):
                ax.spines[side].set_color(AXIS)
                ax.spines[side].set_linewidth(1)
            ax.tick_params(which="both", colors=AXIS, labelcolor=TEXT_MUTED, length=0, pad=6)

        subtitle = (f"run {csv_path.parent.name}  ·  after epoch {epochs[-1]}: "
                    f"loss {loss[-1]:.4f}, error rate {100 * raw_error[-1]:.2f}%")
        if clamped:
            subtitle += f"  ·  {clamped} epoch(s) at 100% accuracy shown as 1 error"
        fig.suptitle("PeakCNN training", x=0.08, y=0.97, ha="left",
                     fontsize=13, fontweight="semibold", color=TEXT_PRIMARY)
        fig.text(0.08, 0.905, subtitle, ha="left", fontsize=9, color=TEXT_SECONDARY)
        legend = ax_loss.legend(handles=[loss_line, err_line], loc="lower left",
                                bbox_to_anchor=(0, 1.01), ncol=2, frameon=False,
                                borderaxespad=0, handlelength=1.6)
        for text in legend.get_texts():
            text.set_color(TEXT_SECONDARY)

        fig.subplots_adjust(left=0.08, right=0.91, top=0.8, bottom=0.12)
        # bbox_inches="tight" grows the margins if long tick labels would be cut off.
        fig.savefig(png_path, facecolor=SURFACE, bbox_inches="tight", pad_inches=0.25)


def spread_labels(positions: list[float], min_gap: float) -> list[float]:
    """Move label positions (axes fractions) apart to at least min_gap, keeping their order and mean."""
    order = sorted(range(len(positions)), key=positions.__getitem__)
    placed = [positions[i] for i in order]
    for k in range(1, len(placed)):
        placed[k] = max(placed[k], placed[k - 1] + min_gap)
    shift = sum(placed) / len(placed) - sum(positions) / len(positions)
    result = [0.0] * len(positions)
    for k, i in enumerate(order):
        result[i] = placed[k] - shift
    return result


def plot_comparison(run_dirs: list[Path], png_path: Path, setting: str, title: str,
                    labels: list[str] | None = None) -> None:
    """Compare the error rates of up to 6 runs: per epoch (left) and over training minutes (right).

    Each run directory must contain config.json and log.csv; runs are labelled by
    config[setting], e.g. setting="batch_size", or by the given labels (useful when
    older runs lack the setting in their config.json). Error rates are clamped to 1/n like
    in plot_training_log. The right chart labels each line at its end; labels that
    would overlap are moved apart and joined to their line end by a thin leader line.
    """
    if not 1 <= len(run_dirs) <= len(RUN_COLORS):
        raise ValueError(f"can compare 1 to {len(RUN_COLORS)} runs, got {len(run_dirs)}")

    if labels is not None and len(labels) != len(run_dirs):
        raise ValueError(f"got {len(labels)} labels for {len(run_dirs)} runs")

    runs = []
    for k, run_dir in enumerate(map(Path, run_dirs)):
        config = json.loads((run_dir / "config.json").read_text())
        with open(run_dir / "log.csv", newline="") as f:
            rows = list(csv.DictReader(f))
        seen = [int(r["functions_seen"]) for r in rows]
        per_epoch = [s - prev for s, prev in zip(seen, [0] + seen[:-1])]
        raw_error = [1.0 - float(r["accuracy"]) for r in rows]
        minutes = []
        total = 0.0
        for r in rows:
            total += float(r["seconds"])
            minutes.append(total / 60)
        runs.append(dict(
            value=labels[k] if labels is not None else config[setting],
            label=labels[k] if labels is not None else f"{setting.replace('_', ' ')} {config[setting]}",
            epochs=[int(r["epoch"]) for r in rows],
            minutes=minutes,
            error=[max(e, 1.0 / n) for e, n in zip(raw_error, per_epoch)],
            final_error=raw_error[-1],
        ))

    lo, hi = decade_range([e for run in runs for e in run["error"]])

    with rc_context(RC):
        fig = Figure(figsize=(10, 4.8), dpi=150, facecolor=SURFACE)
        ax_epoch, ax_time = fig.subplots(1, 2, sharey=True)
        handles = []
        for run, color in zip(runs, RUN_COLORS):
            style = dict(color=color, linewidth=2, solid_capstyle="round",
                         solid_joinstyle="round", clip_on=False)
            (line,) = ax_epoch.plot(run["epochs"], run["error"], **style,
                                    label=f"{run['label']}  ·  {run['minutes'][-1]:.1f} min  ·  "
                                          f"final error {100 * run['final_error']:.2f}%")
            ax_time.plot(run["minutes"], run["error"], **style)
            handles.append(line)

        ax_epoch.set_xlim(1, max(run["epochs"][-1] for run in runs))
        ax_epoch.xaxis.set_major_locator(MaxNLocator(integer=True))
        ax_time.set_xlim(0, max(run["minutes"][-1] for run in runs))
        ax_epoch.set_yscale("log")
        ax_epoch.set_ylim(10.0**lo, 10.0**hi)
        ax_epoch.yaxis.set_major_locator(LogLocator(base=10, numticks=hi - lo + 2))
        ax_epoch.yaxis.set_major_formatter(FuncFormatter(plain_percent))
        ax_epoch.yaxis.set_minor_formatter(NullFormatter())

        ax_epoch.set_xlabel("Epoch (same functions seen)", color=TEXT_SECONDARY)
        ax_time.set_xlabel("Training time (minutes)", color=TEXT_SECONDARY)
        ax_epoch.set_ylabel("Error rate 1 − accuracy (log scale)", color=TEXT_SECONDARY)

        # Direct labels at the line ends of the time chart, spread apart where they would collide.
        ends = [(run["minutes"][-1], run["error"][-1]) for run in runs]
        natural = [(math.log10(e) - lo) / (hi - lo) for _, e in ends]
        placed = spread_labels(natural, LABEL_MIN_GAP)
        x_pad = 0.012 * ax_time.get_xlim()[1]
        for run, (x_end, y_end), y_nat, y_lab in zip(runs, ends, natural, placed):
            moved = abs(y_lab - y_nat) > 1e-9
            ax_time.annotate(
                str(run["value"]), xy=(x_end, y_end), xytext=(x_end + x_pad, y_lab),
                textcoords=("data", "axes fraction"), va="center", ha="left",
                fontsize=9, color=TEXT_SECONDARY, annotation_clip=False, zorder=5,
                bbox=dict(boxstyle="square,pad=0.15", facecolor=SURFACE, edgecolor="none"),
                arrowprops=dict(arrowstyle="-", color=TEXT_MUTED, linewidth=0.8,
                                shrinkA=0, shrinkB=2) if moved else None,
            )

        for ax in (ax_epoch, ax_time):
            ax.set_facecolor(SURFACE)
            ax.grid(axis="y", which="major", color=GRIDLINE, linewidth=1)
            ax.set_axisbelow(True)
            for side in ("top", "right"):
                ax.spines[side].set_visible(False)
            for side in ("left", "bottom"):
                ax.spines[side].set_color(AXIS)
                ax.spines[side].set_linewidth(1)
            ax.tick_params(which="both", colors=AXIS, labelcolor=TEXT_MUTED, length=0, pad=6)

        fig.suptitle(title, x=0.07, y=0.97, ha="left",
                     fontsize=13, fontweight="semibold", color=TEXT_PRIMARY)
        fig.text(0.07, 0.905, "runs " + ", ".join(Path(d).name for d in run_dirs),
                 ha="left", fontsize=9, color=TEXT_SECONDARY)
        legend = ax_epoch.legend(handles=handles, loc="lower left", bbox_to_anchor=(0, 1.01),
                                 ncol=1 if len(runs) <= 3 else 2, frameon=False,
                                 borderaxespad=0, handlelength=1.6, columnspacing=2.0)
        for text in legend.get_texts():
            text.set_color(TEXT_SECONDARY)

        fig.subplots_adjust(left=0.07, right=0.98, top=0.72, bottom=0.12, wspace=0.08)
        fig.savefig(png_path, facecolor=SURFACE, bbox_inches="tight", pad_inches=0.25)


def plot_tuples(params: list, losses: list[float], num_samples: int, png_path: Path, title: str) -> None:
    """Draw the adversarial tuples (data.FunctionParams, one panel each) and save a PNG.

    Each panel shows the function at fine resolution (line) and at the network's num_samples
    sample points (dots), so features that fall between samples are visible. The faint
    horizontal lines at 1/3 and 2/3 are the borders of the valley, edge and peak bands.
    """
    import numpy as np  # local imports: only needed here
    from data import evaluate_params

    fine = np.linspace(0.0, 1.0, 4000)
    grid = np.linspace(0.0, 1.0, num_samples)
    cols = 5
    rows = math.ceil(len(params) / cols)
    with rc_context(RC):
        fig = Figure(figsize=(13, 2.6 * rows + 0.8), dpi=150, facecolor=SURFACE)
        axes = fig.subplots(rows, cols, sharex=True, sharey=True, squeeze=False).ravel()
        for ax, p, loss in zip(axes, params, losses):
            ax.set_facecolor(SURFACE)
            for band in (1 / 3, 2 / 3):
                ax.axhline(band, color=GRIDLINE, linewidth=1, zorder=0)
            ax.scatter(grid, evaluate_params(p, grid), s=5, color=TEXT_MUTED, linewidths=0, zorder=2)
            ax.plot(fine, evaluate_params(p, fine), color=LOSS_COLOR, linewidth=1,
                    solid_capstyle="round", zorder=3)
            peaks = p.pattern.count("P")
            ax.set_title(f"{p.pattern or '(none)'}  ·  {peaks} peak{'s' if peaks != 1 else ''}  ·  "
                         f"loss {loss:.3g}", fontsize=9, color=TEXT_SECONDARY, loc="left")
            ax.set_xlim(0, 1)
            ax.set_ylim(-0.02, 1.02)
            ax.set_xticks([0, 0.5, 1], labels=["0", "0.5", "1"])
            ax.set_yticks([0, 1 / 3, 2 / 3, 1], labels=["0", "1/3", "2/3", "1"])
            for side in ("top", "right"):
                ax.spines[side].set_visible(False)
            for side in ("left", "bottom"):
                ax.spines[side].set_color(AXIS)
            ax.tick_params(colors=AXIS, labelcolor=TEXT_MUTED, length=0, pad=4)
        for ax in axes[len(params):]:
            ax.set_visible(False)
        fig.suptitle(title, x=0.06, y=0.99, ha="left", fontsize=13, fontweight="semibold", color=TEXT_PRIMARY)
        fig.text(0.06, 0.93 if rows > 1 else 0.88,
                 f"blue line: function at fine resolution  ·  gray dots: the {num_samples} samples the network sees",
                 ha="left", fontsize=9, color=TEXT_SECONDARY)
        fig.subplots_adjust(left=0.06, right=0.99, top=0.85 if rows > 1 else 0.72, bottom=0.08,
                            wspace=0.12, hspace=0.35)
        fig.savefig(png_path, facecolor=SURFACE, bbox_inches="tight", pad_inches=0.25)


def plot_fixed_eval(curves: list[tuple[Path, str, str, str]], png_path: Path, title: str) -> None:
    """Loss (left) and error rate (right) per epoch on the fixed evaluation set, for up to 6 curves.

    curves: (run dir, version, legend label, short label for the line ends); version "" reads fixed_loss / fixed_accuracy, "x" reads
    fixed_loss_x / fixed_accuracy_x, and so on (train.FIXED_EVAL_FUNCTIONS). Both panels are
    logarithmic; an epoch without errors is shown as one error (1/n for the n fixed functions).
    """
    if not 1 <= len(curves) <= len(RUN_COLORS):
        raise ValueError(f"can draw 1 to {len(RUN_COLORS)} curves, got {len(curves)}")
    data = []
    for run_dir, version, label, short in curves:
        run_dir = Path(run_dir)
        n = json.loads((run_dir / "config.json").read_text())["fixed_eval_functions"]
        with open(run_dir / "log.csv", newline="") as f:
            rows = list(csv.DictReader(f))
        suffix = f"_{version}" if version else ""
        loss = [float(r[f"fixed_loss{suffix}"]) for r in rows]
        raw_error = [1.0 - float(r[f"fixed_accuracy{suffix}"]) for r in rows]
        data.append(dict(label=label, short=short, epochs=[int(r["epoch"]) for r in rows], loss=loss,
                         error=[max(e, 1.0 / n) for e in raw_error], final_error=raw_error[-1], n=n))

    with rc_context(RC):
        fig = Figure(figsize=(11, 4.8), dpi=150, facecolor=SURFACE)
        ax_loss, ax_err = fig.subplots(1, 2)
        handles = []
        for d, color in zip(data, RUN_COLORS):
            style = dict(color=color, linewidth=1.5, solid_capstyle="round", solid_joinstyle="round")
            (line,) = ax_loss.plot(d["epochs"], d["loss"], **style,
                                   label=f"{d['label']}  ·  final loss {d['loss'][-1]:.4f}, "
                                         f"error {100 * d['final_error']:.2f}%")
            ax_err.plot(d["epochs"], d["error"], **style)
            handles.append(line)

        for ax, key, fmt, ylabel in ((ax_loss, "loss", plain_decimal, "Loss (cross-entropy, log scale)"),
                                     (ax_err, "error", plain_percent, "Error rate 1 − accuracy (log scale)")):
            lo, hi = decade_range([v for d in data for v in d[key]])
            ax.set_yscale("log")
            ax.set_ylim(10.0**lo, 10.0**hi)
            ax.yaxis.set_major_locator(LogLocator(base=10, numticks=hi - lo + 2))
            ax.yaxis.set_major_formatter(FuncFormatter(fmt))
            ax.yaxis.set_minor_formatter(NullFormatter())
            ax.set_xlim(1, max(d["epochs"][-1] for d in data))
            ax.xaxis.set_major_locator(MaxNLocator(integer=True))
            ax.set_xlabel("Epoch", color=TEXT_SECONDARY)
            ax.set_ylabel(ylabel, color=TEXT_SECONDARY)
            ax.set_facecolor(SURFACE)
            ax.grid(axis="y", which="major", color=GRIDLINE, linewidth=1)
            ax.set_axisbelow(True)
            for side in ("top", "right"):
                ax.spines[side].set_visible(False)
            for side in ("left", "bottom"):
                ax.spines[side].set_color(AXIS)
                ax.spines[side].set_linewidth(1)
            ax.tick_params(which="both", colors=AXIS, labelcolor=TEXT_MUTED, length=0, pad=6)

            # Direct labels at the line ends, spread apart where they would collide.
            natural = [(math.log10(d[key][-1]) - lo) / (hi - lo) for d in data]
            placed = spread_labels(natural, LABEL_MIN_GAP)
            x_end = max(d["epochs"][-1] for d in data)
            for d, y_nat, y_lab in zip(data, natural, placed):
                moved = abs(y_lab - y_nat) > 1e-9
                ax.annotate(d["short"], xy=(d["epochs"][-1], d[key][-1]),
                            xytext=(x_end * 1.015, y_lab), textcoords=("data", "axes fraction"),
                            va="center", ha="left", fontsize=9, color=TEXT_SECONDARY,
                            annotation_clip=False, zorder=5,
                            bbox=dict(boxstyle="square,pad=0.15", facecolor=SURFACE, edgecolor="none"),
                            arrowprops=dict(arrowstyle="-", color=TEXT_MUTED, linewidth=0.8,
                                            shrinkA=0, shrinkB=2) if moved else None)

        fig.suptitle(title, x=0.06, y=0.97, ha="left", fontsize=13, fontweight="semibold",
                     color=TEXT_PRIMARY)
        runs = sorted({Path(c[0]).name for c in curves})
        fig.text(0.06, 0.905, f"the same {data[0]['n']:,} functions after every epoch  ·  runs "
                 + ", ".join(runs), ha="left", fontsize=9, color=TEXT_SECONDARY)
        legend = ax_loss.legend(handles=handles, loc="lower left", bbox_to_anchor=(0, 1.01),
                                ncol=2, frameon=False, borderaxespad=0, handlelength=1.6,
                                columnspacing=2.0)
        for text in legend.get_texts():
            text.set_color(TEXT_SECONDARY)
        fig.subplots_adjust(left=0.06, right=0.94, top=0.72, bottom=0.12, wspace=0.32)
        fig.savefig(png_path, facecolor=SURFACE, bbox_inches="tight", pad_inches=0.25)
